from itertools import permutations

# Generate all possible permutations of 0..6
perms = list(permutations(range(7)))

# Initialize an empty grid
grid = [[0]*7 for _ in range(7)]

# Function to check if a grid is a quasigroup
def is_quasigroup(grid):
    # Check if every row and column is a permutation of 0..6
    for i in range(7):
        if sorted(grid[i]) != list(range(7)) or sorted([grid[j][i] for j in range(7)]) != list(range(7)):
            return False
    # Check if the diagonal is idempotent
    for i in range(7):
        if grid[i][i] != i:
            return False
    # Check if the QG3 property is satisfied
    for i in range(7):
        for j in range(7):
            if grid[grid[i][j]][grid[j][i]] != i:
                return False
    return True

# Function to print the grid as a flat list
def print_grid(grid):
    return [grid[i][j] for i in range(7) for j in range(7)]

# Iterate over all possible permutations
for p in perms:
    # Initialize the grid with the current permutation
    for i in range(7):
        grid[i] = list(p)
    # Check if the grid is a quasigroup
    if is_quasigroup(grid):
        # If it is, print the grid and break the loop
        print(print_grid(grid))
        break
